using System;
using System.IO;
using System.IO.Compression;
using System.Linq;
using System.Net;
using System.Net.Sockets;
using System.Security.Cryptography;
using System.Text;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using System.Drawing;
using System.Windows.Forms;

namespace ShroudWorkshop {
static class WorldTransfer {
    public const int Port=15648, Limit=256*1024*1024;
    public static string[] Slots=Enumerable.Range(0,10).Select(i=>"world"+i+".ksd").ToArray();
    public static bool Private(IPAddress ip){var b=ip.GetAddressBytes();return b.Length==4&&(b[0]==10||(b[0]==192&&b[1]==168)||(b[0]==172&&b[1]>=16&&b[1]<=31));}
    public static byte[] Random(int n){var b=new byte[n];using(var r=RandomNumberGenerator.Create())r.GetBytes(b);return b;}
    public static byte[] Key(string s){byte[] k;try{k=Convert.FromBase64String(s.Trim());}catch{throw new Exception("Paste the complete pairing key from the receiving PC.");}if(k.Length!=32)throw new Exception("The pairing key must contain 32 random bytes.");return k;}
    static byte[] Mac(byte[] key,byte[] data){using(var h=new HMACSHA256(key))return h.ComputeHash(data);}
    static bool Equal(byte[] a,byte[] b){int d=a.Length^b.Length;for(int i=0;i<Math.Min(a.Length,b.Length);i++)d|=a[i]^b[i];return d==0;}
    static byte[] Read(Stream s,int n){var b=new byte[n];int p=0;while(p<n){int r=s.Read(b,p,n-p);if(r==0)throw new EndOfStreamException("Connection closed before the transfer completed.");p+=r;}return b;}
    public static void WritePacket(Stream s,byte[] key,byte[] nonce,byte[] plain){using(var aes=Aes.Create()){aes.Key=Mac(key,Encoding.ASCII.GetBytes("Workshop encryption v1"));aes.GenerateIV();byte[] enc;using(var x=aes.CreateEncryptor())enc=x.TransformFinalBlock(plain,0,plain.Length);var body=aes.IV.Concat(enc).ToArray();var tag=Mac(key,nonce.Concat(body).ToArray());var length=BitConverter.GetBytes(body.Length);s.Write(length,0,4);s.Write(body,0,body.Length);s.Write(tag,0,tag.Length);s.Flush();}}
    public static byte[] ReadPacket(Stream s,byte[] key,byte[] nonce){int n=BitConverter.ToInt32(Read(s,4),0);if(n<32||n>Limit+1024)throw new Exception("Invalid or oversized transfer.");var body=Read(s,n);if(!Equal(Read(s,32),Mac(key,nonce.Concat(body).ToArray())))throw new Exception("Pairing key mismatch or damaged transfer. No files were changed.");using(var aes=Aes.Create()){aes.Key=Mac(key,Encoding.ASCII.GetBytes("Workshop encryption v1"));aes.IV=body.Take(16).ToArray();using(var x=aes.CreateDecryptor())return x.TransformFinalBlock(body,16,body.Length-16);}}
    public static bool WorldFile(string name,string slot){return String.Equals(name,slot,StringComparison.Ordinal); }
    public static void Closed(){if(System.Diagnostics.Process.GetProcessesByName("enshrouded").Length>0||Data.Running)throw new Exception("Close Enshrouded and stop the dedicated server, then try again.");}
    public static byte[] Pack(string folder,string slot){Closed();var files=Directory.GetFiles(folder).Where(f=>WorldFile(Path.GetFileName(f),slot)).ToArray();if(!files.Any(f=>Path.GetFileName(f)==slot||Regex.IsMatch(Path.GetFileName(f),"^"+Regex.Escape(slot)+"-[0-9]$")))throw new Exception("No Enshrouded 1.0 world file found for the selected slot. Open older worlds in the game first to convert them.");long total=files.Sum(f=>new FileInfo(f).Length);if(total>Limit)throw new Exception("World exceeds the 256 MB transfer limit.");using(var m=new MemoryStream()){using(var zip=new ZipArchive(m,ZipArchiveMode.Create,true)){foreach(var f in files){if((File.GetAttributes(f)&FileAttributes.ReparsePoint)!=0)throw new Exception("Linked save files are not supported.");zip.CreateEntryFromFile(f,Path.GetFileName(f),CompressionLevel.Optimal);}}return m.ToArray();}}
    public static string Install(byte[] data,string folder,string target){Closed();if(!Directory.Exists(folder))throw new Exception("Choose an existing destination save folder.");if((File.GetAttributes(folder)&FileAttributes.ReparsePoint)!=0)throw new Exception("Linked save folders are not supported.");using(var m=new MemoryStream(data))using(var zip=new ZipArchive(m,ZipArchiveMode.Read)){if(zip.Entries.Count!=1)throw new Exception("Invalid world package.");string source=Slots.FirstOrDefault(s=>zip.Entries.All(e=>WorldFile(e.FullName,s)));if(source==null||!zip.Entries.Any(e=>e.FullName==source||Regex.IsMatch(e.FullName,"^"+Regex.Escape(source)+"-[0-9]$")))throw new Exception("Package contains unrecognized world files.");if(zip.Entries.Sum(e=>e.Length)>Limit||zip.Entries.Select(e=>e.FullName).Distinct(StringComparer.OrdinalIgnoreCase).Count()!=zip.Entries.Count)throw new Exception("Invalid or oversized world package.");string backup=Path.Combine(Data.Home,"world-backups","transfer-"+DateTime.Now.ToString("yyyyMMdd-HHmmss-fffffff"));Directory.CreateDirectory(backup);var old=Directory.GetFiles(folder).Where(f=>WorldFile(Path.GetFileName(f),target)).ToArray();foreach(var f in old)File.Copy(f,Path.Combine(backup,Path.GetFileName(f)));string stage=Path.Combine(backup,"incoming");Directory.CreateDirectory(stage);foreach(var e in zip.Entries)e.ExtractToFile(Path.Combine(stage,target+e.FullName.Substring(source.Length)));Closed();string destination=Path.Combine(folder,target);if(File.Exists(destination)&&(File.GetAttributes(destination)&FileAttributes.ReparsePoint)!=0)throw new Exception("Linked destination files are not supported.");string temporary=Path.Combine(folder,".workshop-transfer-"+Guid.NewGuid().ToString("N"));try{File.Copy(Path.Combine(stage,target),temporary);if(File.Exists(destination))File.Replace(temporary,destination,null);else File.Move(temporary,destination);}finally{if(File.Exists(temporary))File.Delete(temporary);}return backup;}}
}
class TransferWindow:Form {
    TextBox folder,address,key; ComboBox slot,bind; Label status; Button send,receive,stop; TcpListener listener; TcpClient active; bool working;
    public TransferWindow(string serverFolder){Text="World Transfers · LAN companion";Size=new Size(840,720);MinimumSize=new Size(800,700);Font=new Font("Segoe UI",10);StartPosition=FormStartPosition.CenterParent;BackColor=Color.FromArgb(242,245,247);
        var layout=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(24),ColumnCount=1,RowCount=0,AutoScroll=true};Controls.Add(layout);
        Add(layout,new Label{Text="Move a world between your PCs",Font=new Font("Segoe UI",19,FontStyle.Bold),Height=48});
        Add(layout,new Label{Text="Open this window on both PCs. On the destination, select Receive. On the source, enter its IP and pairing key, then Send. Reverse the roles to copy back. Characters are never transferred.",Height=65});
        Add(layout,new Label{Text="Save folder on THIS computer (Steam Cloud users: select the correct Steam userdata\\…\\1203620\\remote folder)",Height=45});
        folder=new TextBox{Text=Directory.Exists(serverFolder)?serverFolder:Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"Saved Games","keen games","Enshrouded","default")};Add(layout,folder);
        var browse=new Button{Text="Choose save folder…",Height=34};browse.Click+=(s,e)=>{using(var d=new FolderBrowserDialog()){d.SelectedPath=folder.Text;if(d.ShowDialog(this)==DialogResult.OK)folder.Text=d.SelectedPath;}};Add(layout,browse);
        Add(layout,new Label{Text="World slot on THIS computer — dedicated servers use slot 1",Height=28});slot=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList};for(int i=0;i<10;i++)slot.Items.Add("World "+(i+1)+"  ·  "+WorldTransfer.Slots[i]);slot.SelectedIndex=0;Add(layout,slot);folder.TextChanged+=(s,e)=>RefreshSlots();RefreshSlots();
        Add(layout,new Label{Text="This PC's LAN address (used when receiving)",Height=28});bind=new ComboBox{DropDownStyle=ComboBoxStyle.DropDownList};foreach(var ip in Dns.GetHostAddresses(Dns.GetHostName()).Where(WorldTransfer.Private))bind.Items.Add(ip.ToString());if(bind.Items.Count>0)bind.SelectedIndex=0;Add(layout,bind);
        Add(layout,new Label{Text="Other PC's LAN address (used when sending)",Height=28});address=new TextBox{Text="192.168.4.42"};Add(layout,address);
        Add(layout,new Label{Text="Pairing key — generated by Receive; copy it privately to the source PC",Height=28});key=new TextBox();Add(layout,key);
        var buttons=new FlowLayoutPanel{Height=45,Dock=DockStyle.Fill};receive=new Button{Text="Receive a world",Width=185,Height=36};send=new Button{Text="Send selected world",Width=195,Height=36};stop=new Button{Text="Stop waiting",Width=155,Height=36,Enabled=false};buttons.Controls.AddRange(new Control[]{receive,send,stop});Add(layout,buttons);
        status=new Label{Text="Ready. Close the game and stop the server on both PCs. Transfers replace a world; they do not merge it. The receiver makes a backup and asks before replacing files. For Steam Cloud, exit Steam before receiving and resolve any later sync conflict using the transferred local files.",Height=110};Add(layout,status);
        receive.Click+=async(s,e)=>await Receive();send.Click+=async(s,e)=>await Send();stop.Click+=(s,e)=>Cancel();FormClosing+=(s,e)=>{if(working){e.Cancel=true;MessageBox.Show(this,"Wait for the transfer to finish. Use Stop waiting to cancel a receiver.");}else Cancel();};
    }
    void RefreshSlots(){int selected=Math.Max(0,slot.SelectedIndex);slot.Items.Clear();foreach(string name in WorldTransfer.Slots){string path=Path.Combine(folder.Text,name),detail="empty slot";try{if(File.Exists(path))detail="saved "+File.GetLastWriteTime(path).ToString("MMM d, yyyy HH:mm");}catch{}slot.Items.Add("World "+(slot.Items.Count+1)+"  ·  "+name+"  ·  "+detail);}slot.SelectedIndex=selected;}
    static void Add(TableLayoutPanel p,Control c){c.Dock=DockStyle.Top;c.Margin=new Padding(0,0,0,8);p.Controls.Add(c);}
    void State(bool busy){working=busy;send.Enabled=receive.Enabled=folder.Enabled=slot.Enabled=bind.Enabled=address.Enabled=!busy;key.ReadOnly=busy;stop.Enabled=busy&&listener!=null;}
    void Cancel(){if(listener!=null)listener.Stop();if(active!=null)active.Close();}
    async Task Receive(){try{WorldTransfer.Closed();IPAddress ip;if(!IPAddress.TryParse(bind.Text,out ip)||!WorldTransfer.Private(ip))throw new Exception("Choose this computer's private IPv4 address.");string dest=Path.GetFullPath(folder.Text),target=WorldTransfer.Slots[slot.SelectedIndex];if(!Directory.Exists(dest))throw new Exception("Choose an existing save folder.");var secret=WorldTransfer.Random(32);key.Text=Convert.ToBase64String(secret);listener=new TcpListener(ip,WorldTransfer.Port);listener.Start(1);State(true);status.Text="Waiting on "+ip+":"+WorldTransfer.Port+". Copy the pairing key to the source PC. Allow this app on PRIVATE networks if Windows asks. This session accepts one connection and expires in five minutes.";
        var accept=listener.AcceptTcpClientAsync();if(await Task.WhenAny(accept,Task.Delay(300000))!=accept){listener.Stop();throw new Exception("Receive session expired. Start Receive again for a new key.");}active=await accept;listener.Stop();listener=null;stop.Enabled=true;var remote=((IPEndPoint)active.Client.RemoteEndPoint).Address;if(!WorldTransfer.Private(remote))throw new Exception("Only private LAN addresses are accepted.");active.ReceiveTimeout=30000;active.SendTimeout=30000;var stream=active.GetStream();var nonce=WorldTransfer.Random(32);byte[] package=await Task.Run(()=>{stream.Write(nonce,0,32);return WorldTransfer.ReadPacket(stream,secret,nonce);});status.Text="World received from "+remote+". Waiting for your approval.";
        if(MessageBox.Show(this,"Replace world slot "+(Array.IndexOf(WorldTransfer.Slots,target)+1)+" in:\n"+dest+"\n\nSource PC: "+remote+"\nA backup will be created first. This does not merge worlds.\nConfirm the destination folder and close Steam if it manages this folder.","Approve incoming world",MessageBoxButtons.YesNo,MessageBoxIcon.Warning)!=DialogResult.Yes){WorldTransfer.WritePacket(stream,secret,nonce,Encoding.UTF8.GetBytes("Declined: destination was not changed."));return;}
        string backup=WorldTransfer.Install(package,dest,target);WorldTransfer.WritePacket(stream,secret,nonce,Encoding.UTF8.GetBytes("Installed successfully. Backup: "+backup));status.Text="World installed. Previous destination saved at: "+backup;
        }catch(Exception ex){status.Text="Receive stopped: "+ex.Message;}finally{Cancel();listener=null;active=null;State(false);}}
    async Task Send(){try{IPAddress ip;if(!IPAddress.TryParse(address.Text.Trim(),out ip)||!WorldTransfer.Private(ip))throw new Exception("Enter the receiving PC's private IPv4 address.");byte[] secret=WorldTransfer.Key(key.Text);var package=WorldTransfer.Pack(folder.Text,WorldTransfer.Slots[slot.SelectedIndex]);State(true);status.Text="Connecting and sending encrypted world. The receiver must approve the replacement.";active=new TcpClient();var connect=active.ConnectAsync(ip,WorldTransfer.Port);if(await Task.WhenAny(connect,Task.Delay(10000))!=connect)throw new Exception("Connection timed out. Start Receive on the other PC and check its private-network firewall permission.");await connect;active.ReceiveTimeout=300000;active.SendTimeout=30000;var stream=active.GetStream();string result=await Task.Run(()=>{var nonce=new byte[32];int p=0;while(p<32){int n=stream.Read(nonce,p,32-p);if(n==0)throw new EndOfStreamException();p+=n;}WorldTransfer.WritePacket(stream,secret,nonce,package);return Encoding.UTF8.GetString(WorldTransfer.ReadPacket(stream,secret,nonce));});status.Text=result;
        }catch(Exception ex){status.Text="Send failed: "+ex.Message;}finally{if(active!=null)active.Close();active=null;State(false);}}
}
}



